const icons={school:'M3 21h18M5 21V9l7-6 7 6v12M9 21v-6h6v6M9 10h.01M15 10h.01',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',door:'M4 21h16M6 21V3h12v18M13 12h.01',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',chart:'M4 3v18h17M8 16v-5M13 16V7M18 16v-8',leaf:'M20 3C5 2 1 11 6 17c6 6 15 2 14-14ZM4 21l11-11',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',bolt:'m13 2-9 12h7l-1 8 10-13h-7z',arrow:'M5 12h14m-5-5 5 5-5 5',info:'M12 11v6M12 7h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',snow:'M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M9 4l3 3 3-3M9 20l3-3 3 3M3 11l4-1-1-4M21 13l-4 1 1 4M6 18l1-4-4-1M18 6l-1 4 4 1',thermo:'M9 14.5V5a3 3 0 0 1 6 0v9.5a5 5 0 1 1-6 0M12 8v9',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2zM12 9v5M12 17h.01',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0M8 16a6 6 0 0 1 8 0M12 20h.01',close:'m6 6 12 12M6 18 18 6'};
export const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const nav=[['overview','grid','학교 현황'],['rooms','door','교실 둘러보기'],['alerts','bell','낭비 알림'],['stats','chart','에너지 통계']];
for(const id of ['desktop-nav','mobile-nav']) document.getElementById(id).innerHTML=nav.map(([key,i,label])=>`<a class="nav-item ${key==='overview'?'active':''}" href="#${key}">${icon(i)}<span>${label}</span></a>`).join('');
document.querySelectorAll('.install-trigger').forEach(el=>el.addEventListener('click',()=>document.getElementById('install-dialog').showModal()));
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>document.getElementById(el.dataset.close).close()));

import {createRooms,evaluateRoom,priorityRooms,summarize,changeSensor,applyScenario,occupancyLabel,isActionable} from './model.js';
let rooms=createRooms();
let view='overview',floorFilter='all',roomFilter='all',query='',selectedRoom=null;
let history=[];
let toastTimer;
const app=document.getElementById('app');
const roomDialog=document.getElementById('room-dialog');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const format=n=>n.toLocaleString('ko-KR');
const badge=r=>{const e=evaluateRoom(r);return `<span class="badge ${e.level}">${e.label}</span>`;};
const empty=(message)=>`<div class="empty">${icon('check')}<h3>${message}</h3><p>교실 둘러보기에서 각 공간의 상태를 확인할 수 있어요.</p></div>`;
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),3600);}
function statsCards(){const s=summarize(rooms);return `<div class="stats-grid">
 <div class="stat"><div class="stat-label">현재 사용 전력 ${icon('bolt')}</div><div class="stat-number number">${s.powerKW.toFixed(1)}<span>kW</span></div><div class="stat-note">${s.unknown?`${s.unknown}개 교실 데이터 제외`:'12개 교실 합계 · 시연'}</div></div>
 <div class="stat"><div class="stat-label">확인이 필요한 교실 ${icon('alert')}</div><div class="stat-number number">${s.active}<span>/ 12곳</span></div><div class="stat-note"><span class="red">우선 확인 ${s.critical}곳</span> · 상태 불명 ${s.unknown}곳</div></div>
 <div class="stat accent"><div class="stat-label">빈 교실 냉방 의심량 ${icon('leaf')}</div><div class="stat-number number">${s.suspectKWh.toFixed(2)}<span>kWh</span></div><div class="stat-note">현재 지속 구간 · 시연 전력 기반 추정</div></div>
 <div class="stat"><div class="stat-label">가동 중인 에어컨 ${icon('snow')}</div><div class="stat-number number">${s.acCount}<span>대</span></div><div class="stat-note">센서 상태 확인 가능 교실 기준</div></div></div>`;}
function chartMarkup(room=null){
 const multiplier=room?room.baselineW/20000:1;
 const values=[1.1,1.2,1.0,1.0,1.1,1.5,3,9,14,17,18,16,12,16,19,21,23];
 const last=room?room.powerW/1000:summarize(rooms).powerKW;
 const actual=values.map(v=>v*multiplier);actual[16]=last;
 const base=values.map((v,i)=>(v*.9+(i>13?-2:0))*multiplier);
 const max=Math.max(...actual,...base,room?3:30)*1.1;
 const y=v=>170-v/max*150;
 const points=actual.map((v,i)=>`${46+i*35.2},${y(v).toFixed(1)}`).join(' ');
 const baseline=base.map((v,i)=>`${46+i*35.2},${y(v).toFixed(1)}`).join(' ');
 return `<div class="chart-key"><span><i></i>사용 전력 예시</span><span><i class="baseline"></i>평소 패턴 예시</span></div><svg class="chart-svg" viewBox="0 0 650 204" role="img" aria-label="하루 시간대별 전력 시연 그래프. 현재 값 ${last.toFixed(1)}킬로와트. 과거 곡선은 예시입니다."><defs><linearGradient id="area-${room?.id||'school'}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#14a58c" stop-opacity=".2"/><stop offset="1" stop-color="#14a58c" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>{const v=max*i/3;return `<line x1="46" x2="617" y1="${y(v)}" y2="${y(v)}" stroke="#edf1f3"/><text x="32" y="${y(v)+4}" text-anchor="end">${v.toFixed(0)}</text>`;}).join('')}<text x="7" y="10">kW</text><polygon points="46,170 ${points} 609.2,170" fill="url(#area-${room?.id||'school'})"/><polyline points="${baseline}" fill="none" stroke="#b5c3c9" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${points}" fill="none" stroke="#159983" stroke-width="2.5" stroke-linejoin="round"/><circle cx="609.2" cy="${y(last)}" r="4" fill="#159983" stroke="white" stroke-width="2"/>${[0,4,8,12,16].map(i=>`<text x="${46+i*35.2}" y="197" text-anchor="middle">${String(i).padStart(2,'0')}:00</text>`).join('')}</svg>`;
}
function buildingMap(){const floors=floorFilter==='all'?[3,2,1]:[Number(floorFilter)];return `<section class="panel"><div class="panel-head"><div><h2>우리학교 공간 현황</h2><p>교실을 누르면 상세 상태를 볼 수 있어요.</p></div><span class="badge">본관 · 12곳</span></div><div class="building-bar"><div class="segmented" aria-label="층 선택">${[['all','전체'],['1','1층'],['2','2층'],['3','3층']].map(([v,l])=>`<button data-floor="${v}" class="${floorFilter===v?'selected':''}" aria-pressed="${floorFilter===v}">${l}</button>`).join('')}</div><div class="status-legend"><span><i class="legend-dot"></i>정상</span><span><i class="legend-dot warning"></i>관심</span><span><i class="legend-dot critical"></i>확인 필요</span><span><i class="legend-dot unknown"></i>미수신</span></div></div><div class="room-map">${floors.map(f=>`<div class="floor-row"><span class="floor-label">${f}F</span>${rooms.filter(r=>r.floor===f).map(r=>{const e=evaluateRoom(r);return `<button class="room-tile ${e.level}" data-room="${r.id}" aria-label="${r.name}, ${e.label}, 상세 보기"><strong>${r.name}</strong><span class="tile-state"><i class="legend-dot ${e.level}"></i>${e.level==='critical'?'확인 필요':e.label}</span><small>${r.stale?'수신 중단':`${(r.powerW/1000).toFixed(2)} kW`}</small></button>`;}).join('')}</div>`).join('')}<p class="map-note">${icon('info')} 교실 배치는 시연용입니다. ‘정상’은 낭비 미탐지를 뜻합니다.</p></div></section>`;}
function priorityPanel(){const list=priorityRooms(rooms).slice(0,3);return `<section class="panel"><div class="panel-head"><div><h2>먼저 확인해 주세요</h2><p>지속 시간과 상태 조합에 따른 우선순위</p></div><a class="panel-link" href="#alerts">전체 ${icon('arrow')}</a></div><div class="priority-list">${list.length?list.map((r,i)=>`<button class="priority-item" data-room="${r.id}"><span class="rank">0${i+1}</span><div class="priority-main"><div class="priority-title"><strong>${r.name}</strong>${badge(r)}</div><p>${evaluateRoom(r).reason}</p><span class="priority-meta">${r.building} ${r.floor}층 · ${r.acknowledged?'알림 확인함 · 조건 지속':'현장 확인 전'}</span></div></button>`).join(''):empty('지금 확인할 알림이 없어요')}</div><div class="notice-strip">${icon('info')} 낭비 의심 신호입니다. 실제 재실·환기 상황을 확인해 주세요.</div></section>`;}
function chartPanel(){return `<section class="panel wide"><div class="panel-head"><div><h2>오늘의 에너지 흐름</h2><p>00:00–16:40 · 과거 곡선은 시연 예시</p></div><a class="panel-link" href="#stats">통계 보기 ${icon('arrow')}</a></div><div class="chart-layout"><div>${chartMarkup()}</div><div class="chart-summary"><span>빈 교실에서 계속된 냉방</span><strong>${summarize(rooms).suspectKWh.toFixed(2)} <small>kWh</small></strong><p>현재 의심 구간에 사용된<br>냉방 전력량의 추정값이에요.</p><hr><small>문 열림으로 인한 추가 손실은<br>이 값에 더하지 않았어요.</small></div></div></section>`;}
function demoBar(){return `<div class="demo-bar"><div><strong>직접 바꿔보는 학교 상황</strong><p>선택하면 가상 센서 상태가 바뀝니다. 새로고침하면 초기화됩니다.</p></div><div class="demo-actions"><button data-scenario="waste">빈 교실 + 열린 문</button><button data-scenario="normal">모두 정상</button><button data-scenario="after-school">방과 후 미종료</button><button data-scenario="sensor-loss">센서 연결 끊김</button></div></div>`;}
function roomsPage(){const filtered=rooms.filter(r=>(roomFilter==='all'||(roomFilter==='attention'?isActionable(r):evaluateRoom(r).level===roomFilter))&&(r.name.includes(query)||r.id.includes(query)));return `<div class="toolbar"><div class="filters">${[['all','전체 12곳'],['attention','확인 필요'],['normal','정상'],['unknown','연결 확인']].map(([k,l])=>`<button class="filter ${roomFilter===k?'selected':''}" data-filter="${k}" aria-pressed="${roomFilter===k}">${l}</button>`).join('')}</div><input class="search" id="room-search" type="search" placeholder="교실 이름 또는 번호 검색" aria-label="교실 검색" value="${escapeHTML(query)}"></div><div class="room-list">${filtered.length?filtered.map(r=>`<button class="room-card" data-room="${r.id}"><div class="room-card-top"><h3>${r.name}</h3>${badge(r)}</div><div class="location">${r.building} ${r.floor}층 · ${r.id}호</div><div class="power number">${r.stale?'—':(r.powerW/1000).toFixed(2)} <small>kW</small></div><div class="room-sensors"><span>${icon('users')}${occupancyLabel(r)}</span><span>${icon('snow')}${r.stale?'확인 불가':`냉방 ${r.ac?'가동':'꺼짐'}`}</span><span>${icon('door')}${r.stale?'확인 불가':`문 ${r.door?'열림':'닫힘'}`}</span><span>${icon('thermo')}${r.stale?'—':r.temperature.toFixed(1)}°C</span></div><p class="reason">${evaluateRoom(r).reason}</p></button>`).join(''):empty('조건에 맞는 교실이 없어요')}</div>${demoBar()}`;}
function alertsPage(){const list=priorityRooms(rooms);return `<div class="stats-note">알림의 ‘확인함’은 읽음 표시입니다. 센서 상태에서 원인이 해소되어야 알림이 사라집니다.</div><section class="panel"><div class="panel-head"><h2>현재 알림 <span class="muted">${list.length}</span></h2><span class="badge">시연 규칙 기반</span></div>${list.length?list.map(r=>{const e=evaluateRoom(r);return `<div class="alert-row"><span class="alert-symbol ${e.level}">${icon(e.level==='unknown'?'wifi':'alert')}</span><div class="alert-copy"><h3>${r.name}${badge(r)}</h3><p>${e.reason}</p><small>${r.building} ${r.floor}층 · ${r.acknowledged?'확인함 · 원인 조건 지속':'아직 확인하지 않음'}</small></div><div class="alert-actions"><button class="secondary" data-ack="${r.id}" ${r.acknowledged?'disabled':''}>${r.acknowledged?'확인함':'알림 확인'}</button><button class="secondary" data-room="${r.id}">상세 ${icon('arrow')}</button></div></div>`;}).join(''):empty('현재 활성 알림이 없어요')}</section>${demoBar()}`;}
function statsPage(){const s=summarize(rooms);return `${statsCards()}<div class="stats-note">이 초안은 센서 상태 조합과 예시 사용 패턴으로 낭비를 추정합니다. 아직 학습된 AI 모델이나 실제 절감 실적은 포함하지 않습니다.</div><div class="overview-grid">${chartPanel()}<section class="panel"><div class="panel-head"><h2>층별 현재 전력</h2><span class="badge">가상 데이터</span></div><div class="bar-report">${[1,2,3].map(f=>{const value=rooms.filter(r=>r.floor===f&&!r.stale).reduce((sum,r)=>sum+r.powerW,0)/1000;return `<div class="bar-row"><strong>본관 ${f}층</strong><div class="bar-track"><i style="width:${s.powerKW?value/s.powerKW*100:0}%"></i></div><span>${value.toFixed(1)} kW</span></div>`;}).join('')}</div></section><section class="panel"><div class="panel-head"><h2>추정값은 어떻게 계산하나요?</h2></div><div class="method"><h3>빈 교실 냉방 의심량</h3><p>비어 있음으로 추정되고 냉방이 5분 이상 지속된 교실의 냉방 전력 × 지속 시간입니다.</p><p>움직임 센서 하나로 빈 교실을 확정할 수 없어요. 문 열림에 따른 추가 손실량과 실제 절감량도 이 값에서 알 수 없습니다.</p><p>전기요금과 탄소 환산은 학교의 요금제와 검증된 배출계수를 연결한 뒤 추가할 예정입니다.</p></div></section></div>${demoBar()}`;}
function render(){
 const texts={overview:['학교 에너지 현황','지금 확인이 필요한 교실을 살펴보세요.'],rooms:['교실 둘러보기','교실별 재실, 문, 냉방 상태를 확인하세요.'],alerts:['에너지 낭비 알림','의심 신호의 이유를 확인하고 현장에서 살펴보세요.'],stats:['에너지 통계','학교 전체의 사용 흐름과 추정 기준을 확인하세요.']};
 document.getElementById('page-title').textContent=texts[view][0];document.getElementById('page-subtitle').textContent=texts[view][1];document.getElementById('breadcrumb').textContent=nav.find(n=>n[0]===view)[2];document.title=`teapot · ${texts[view][0]}`;
 document.querySelectorAll('.nav-item').forEach(el=>{const active=el.getAttribute('href')===`#${view}`;el.classList.toggle('active',active);active?el.setAttribute('aria-current','page'):el.removeAttribute('aria-current');});
 const offline=navigator.onLine?'':`<div class="offline-note">오프라인입니다. 아래는 기기에 남아 있는 시연 화면이며 실제 학교의 현재 상태가 아닙니다.</div>`;
 app.innerHTML=offline+(view==='overview'?`${statsCards()}<div class="overview-grid">${buildingMap()}${priorityPanel()}${chartPanel()}</div>${demoBar()}`:view==='rooms'?roomsPage():view==='alerts'?alertsPage():statsPage());
}
function openRoom(id){const room=rooms.find(r=>r.id===id);if(!room)throw new Error('Unknown room');selectedRoom=id;renderDetail();if(!roomDialog.open)roomDialog.showModal();}
function renderDetail(){const r=rooms.find(r=>r.id===selectedRoom);if(!r)return;const e=evaluateRoom(r);const actionable=isActionable(r);
 const action=e.type==='vacant-open'?'교실의 실제 재실·환기 여부를 확인하고, 불필요한 냉방이면 에어컨을 꺼주세요.':e.type==='vacant-ac'?'시간표와 실제 재실 여부를 확인한 뒤 냉방 종료를 검토해 주세요.':e.type==='open-door'?'환기 목적의 개방인지 먼저 확인하고, 냉방 중 문 개방 시간을 조정해 주세요.':e.type==='stale'?'센서 전원과 네트워크 연결을 확인해 주세요. 이전 값으로 정상 판단하지 않습니다.':e.type==='unusual'?'컴퓨터와 주변 기기의 미종료 여부를 확인해 주세요. 높은 사용량이 낭비를 확정하지는 않습니다.':'새로운 센서 상태가 일정 시간 지속되는지 관찰합니다.';
 const sensor=(i,n,v,note)=>`<div class="sensor-card"><span class="sensor-name">${icon(i)}${n}</span><strong>${v}</strong><small>${note}</small></div>`;
 const log=history.filter(h=>h.room===r.id).slice(-4).reverse();
 document.getElementById('room-detail').innerHTML=`<div class="detail-head"><div><span class="eyebrow">ROOM ${r.id}</span><h2 id="room-dialog-title">${r.name}</h2><small>${r.building} ${r.floor}층 · 시연 상태</small></div><button class="icon-button" data-close="room-dialog" aria-label="교실 상세 닫기">${icon('close')}</button></div><div class="detail-body"><div class="detail-alert ${e.level}">${badge(r)}<h3 style="margin-top:12px">${e.reason}</h3><p>${action}</p>${actionable?`<div class="actions"><button class="secondary" data-ack="${r.id}" ${r.acknowledged?'disabled':''}>${icon('check')}${r.acknowledged?'알림 확인함 · 원인 조건 지속':'알림 확인'}</button></div>`:''}</div><h3>현재 교실 상태</h3><div class="sensor-grid">${sensor('users','재실 상태',occupancyLabel(r),'시연 입력 · 인원수 판별 아님')}${sensor('door','교실 문',r.stale?'확인 불가':r.door?'열려 있어요':'닫혀 있어요',r.stale?'수신 중단':`현재 조건 ${r.minutes}분 지속`)}${sensor('snow','에어컨',r.stale?'확인 불가':r.ac?'가동 중':'꺼짐','시연 상태 · 실제 제어 아님')}${sensor('bolt','교실 소비전력',r.stale?'—':`${(r.powerW/1000).toFixed(2)} kW`,'교실 전체 · 예시 측정값')}${sensor('thermo','온도',r.stale?'—':`${r.temperature.toFixed(1)}°C`,'실제 냉난방 성능 시뮬레이션 아님')}${sensor('leaf','의심 구간 냉방량',e.estimateKWh==null?'산정 보류':`${e.estimateKWh.toFixed(2)} kWh`,'절감 실적이 아닌 추정량')}</div><h3>사용 전력 흐름</h3><div style="margin-top:16px">${chartMarkup(r)}</div><p class="detail-note">과거 곡선은 예시입니다. 조건 변경은 현재 값에 반영됩니다.</p>${log.length?`<h3>이번 시연의 변경 기록</h3><ul class="timeline">${log.map(h=>`<li>${escapeHTML(h.text)}<small>이 브라우저의 시연 세션</small></li>`).join('')}</ul>`:''}<div class="demo-controls"><h3>시연 센서 변경</h3><p>상태를 바꾼 뒤 ‘5분 경과’를 누르면 판단 결과를 볼 수 있어요. 실제 장치에는 명령을 보내지 않습니다.</p><label class="control-row">재실 신호<select data-sensor="occupied"><option value="yes" ${r.occupied==='yes'?'selected':''}>재실 신호 있음</option><option value="no" ${r.occupied==='no'?'selected':''}>비어 있음 추정</option><option value="unknown" ${r.occupied==='unknown'?'selected':''}>판단 보류</option></select></label><label class="control-row">문 열림<input class="switch" type="checkbox" data-sensor="door" ${r.door?'checked':''}></label><label class="control-row">에어컨 가동<input class="switch" type="checkbox" data-sensor="ac" ${r.ac?'checked':''}></label><label class="control-row">센서 수신 중단<input class="switch" type="checkbox" data-sensor="stale" ${r.stale?'checked':''}></label><div class="control-row"><span>현재 조건 지속 시간: ${r.minutes}분</span><button class="secondary" data-advance="${r.id}" ${r.minutes>=180?'disabled':''}>5분 경과</button></div></div><p class="detail-note">‘비어 있음’은 센서와 시간표 등을 조합해 추정해야 합니다. 현재는 시연 입력을 사용하며 자동 에어컨 제어를 제공하지 않습니다.</p></div>`;
}
function acknowledge(id){const r=rooms.find(r=>r.id===id);if(!r||!isActionable(r))throw new Error('No active alert');r.acknowledged=true;history.push({room:id,text:'알림 확인함 · 센서의 원인 조건은 계속 확인'});render();if(roomDialog.open)renderDetail();toast('알림을 확인했습니다. 원인 조건은 계속 모니터링해요.');return {roomId:id,acknowledged:true,resolved:false};}
function setScenario(name){rooms=applyScenario(name);history=[];render();if(roomDialog.open)renderDetail();toast('시연 상황을 변경했습니다.');}
function updateSensor(id,key,value){const index=rooms.findIndex(r=>r.id===id);if(index<0)throw new Error('Unknown room');const before=evaluateRoom(rooms[index]);rooms[index]=changeSensor(rooms[index],key,value);const after=evaluateRoom(rooms[index]);const labels={occupied:'재실 신호 변경',door:value?'문 열림':'문 닫힘',ac:value?'시연 에어컨 가동':'시연 에어컨 꺼짐',stale:value?'센서 수신 중단':'센서 수신 복구',minutes:`조건 지속 ${value}분`};history.push({room:id,text:labels[key]});if(before.level!=='normal'&&after.level==='normal')history.push({room:id,text:after.type==='observing'?'이전 조건 해제 · 새 조건 관찰 중':'원인 조건 해제'});render();if(roomDialog.open)renderDetail();return {roomId:id,status:after.label,reason:after.reason};}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const d=button.dataset;if(d.room)openRoom(d.room);if(d.floor){floorFilter=d.floor;render();}if(d.filter){roomFilter=d.filter;render();}if(d.ack)acknowledge(d.ack);if(d.scenario)setScenario(d.scenario);if(d.close)document.getElementById(d.close).close();if(d.advance){const r=rooms.find(r=>r.id===d.advance);updateSensor(r.id,'minutes',Math.min(180,r.minutes+5));}});
document.addEventListener('change',event=>{const key=event.target.dataset.sensor;if(key)updateSensor(selectedRoom,key,event.target.type==='checkbox'?event.target.checked:event.target.value);});
document.addEventListener('input',event=>{if(event.target.id==='room-search'){query=event.target.value;const start=event.target.selectionStart;render();const input=document.getElementById('room-search');input.focus();if(input.type==='text')input.setSelectionRange(start,start);}});
function route(){const desired=location.hash.slice(1);view=nav.some(n=>n[0]===desired)?desired:'overview';render();window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',route);
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
roomDialog.addEventListener('close',()=>{selectedRoom=null;});
function network(){const label=document.getElementById('network-label');label.textContent=navigator.onLine?'온라인':'오프라인';label.classList.toggle('offline',!navigator.onLine);render();}
window.addEventListener('online',network);window.addEventListener('offline',network);
let installPrompt=null;
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.getElementById('native-install').hidden=false;});
document.getElementById('native-install').addEventListener('click',async()=>{if(!installPrompt)return;await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;document.getElementById('native-install').hidden=true;});
window.addEventListener('appinstalled',()=>{document.getElementById('install-dialog').close();toast('홈 화면에 teapot을 추가했습니다.');});
route();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{document.getElementById('install-title').textContent='브라우저에서 teapot 사용하기';}));

// Optional WebMCP bridge shares the same state and actions as the visible UI.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tools=[
 {name:'get_school_alerts',description:'Read active demo classroom alerts and school totals. Does not connect to real sensors.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('No arguments expected');return {demo:true,summary:summarize(rooms),alerts:priorityRooms(rooms).map(r=>({id:r.id,name:r.name,...evaluateRoom(r),acknowledged:r.acknowledged}))};}},
 {name:'open_classroom_detail',description:'Navigate to one classroom detail panel without changing its sensors.',inputSchema:{type:'object',properties:{roomId:{type:'string'}},required:['roomId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.roomId!=='string'||Object.keys(input).length!==1)throw new Error('roomId required');openRoom(input.roomId);return {openedRoomId:input.roomId};}},
 {name:'acknowledge_classroom_alert',description:'Mark a demo alert as seen. This does not resolve the cause or control equipment.',inputSchema:{type:'object',properties:{roomId:{type:'string'}},required:['roomId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.roomId!=='string'||Object.keys(input).length!==1)throw new Error('roomId required');return acknowledge(input.roomId);}}
 ];
 for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
